css:
.fx-hm{width:min(1100px,100%);display:grid;gap:1.6em}
.fx-hm .top{display:flex;justify-content:space-between;align-items:end;gap:1em}.fx-hm h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-hm .nav{display:flex;gap:.5em}.fx-hm .nav button{width:2.8em;height:2.8em;border-radius:50%;border:1.5px solid var(--primary);background:transparent;color:var(--primary);cursor:pointer;font-size:1em;transition:background .25s,color .25s,opacity .25s}
.fx-hm .nav button:hover:not(:disabled){background:var(--primary);color:var(--on-primary)}.fx-hm .nav button:disabled{opacity:.35;cursor:default}
.fx-hm .nav button:focus-visible,.fx-hm ol:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hm ol{list-style:none;margin:0 -.6em;padding:.6em .6em .8em;display:flex;gap:1.2em;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding-inline:.6em;scrollbar-width:thin;scrollbar-color:var(--border) transparent;scroll-behavior:smooth;position:relative}
.fx-hm li{position:relative;flex:0 0 min(16em,78%);scroll-snap-align:start;padding-top:2.2em}
.fx-hm li::before{content:"";position:absolute;top:.55em;left:0;right:-1.2em;height:2px;background:var(--border)}
.fx-hm li:last-child::before{right:0;background:linear-gradient(90deg,var(--border),transparent)}
.fx-hm .pt{position:absolute;top:.2em;left:0;width:.9em;height:.9em;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px var(--surface),0 0 0 5.5px var(--accent);transition:transform calc(.3s/var(--speed))}
.fx-hm li:hover .pt{transform:scale(1.25)}
.fx-hm b{display:block;font:600 2.4em/1 var(--font-heading);color:var(--primary);margin-bottom:.25em}
.fx-hm h3{font-size:1.1em;margin-bottom:.3em}.fx-hm li p{opacity:.7;font-size:.92em;max-width:22ch}
@media(prefers-reduced-motion:reduce){.fx-hm ol{scroll-behavior:auto}.fx-hm .pt{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hm .nav button.is-tap:not(:disabled){background:var(--primary);color:var(--on-primary)}
.fx-hm li.is-tap .pt{transform:scale(1.25)}

js:
(function(){document.querySelectorAll('.fx-hm').forEach(function(r){var ol=r.querySelector('ol'),bs=r.querySelectorAll('.nav button');
function step(){var li=ol.children[0];return li.offsetWidth+parseFloat(getComputedStyle(ol).columnGap||19)}
function upd(){bs[0].disabled=ol.scrollLeft<4;bs[1].disabled=ol.scrollLeft+ol.clientWidth>=ol.scrollWidth-4}
bs[0].addEventListener('click',function(){ol.scrollBy({left:-step()})});bs[1].addEventListener('click',function(){ol.scrollBy({left:step()})});
ol.addEventListener('scroll',upd);addEventListener('resize',upd);
ol.addEventListener('keydown',function(e){if(e.key==='ArrowRight'){e.preventDefault();ol.scrollBy({left:step()})}else if(e.key==='ArrowLeft'){e.preventDefault();ol.scrollBy({left:-step()})}});
var d=false,sx=0,sl=0;ol.addEventListener('pointerdown',function(e){if(e.pointerType!=='mouse')return;d=true;sx=e.clientX;sl=ol.scrollLeft;ol.style.scrollSnapType='none';ol.style.scrollBehavior='auto'});
addEventListener('pointermove',function(e){if(d)ol.scrollLeft=sl-(e.clientX-sx)});
addEventListener('pointerup',function(){if(!d)return;d=false;ol.style.scrollSnapType='';ol.style.scrollBehavior=''});
upd()})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
